function divisorGame(n) {
  const wins = new Array(n + 1).fill(false);
  for (let current = 2; current <= n; current++) {
    for (let x = 1; x < current; x++) {
      if (current % x !== 0) {
        continue;
      }
      if (!wins[current - x]) {
        wins[current] = true;
        break;
      }
    }
  }
  return wins[n];
}

