function divisorGame(n) {
  // Top-down minimax with a cache: the player to move wins if some move leaves the opponent in a losing spot.
  const memo = new Map();
  const moverWins = (value) => {
    if (memo.has(value)) return memo.get(value);
    let result = false;
    for (let x = 1; x < value && !result; x++) {
      if (value % x === 0 && !moverWins(value - x)) result = true;
    }
    memo.set(value, result);
    return result;
  };
  return moverWins(n);
}

